pages=[]
def page(path,title,desc,body):
    canonical=base+(path if path!='index.html' else '')
    pages.append(canonical)
    Path(path).write_text(f'''<!doctype html><html lang="en"><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>{e(title)} · The Practical Home</title><meta name="description" content="{e(desc,quote=True)}"><link rel="canonical" href="{canonical}"><link rel="alternate" type="application/rss+xml" title="The Practical Home" href="feed.xml"><link rel="stylesheet" href="assets/site.css"><script defer src="assets/metrics.js" data-endpoint="{e(data['analyticsEndpoint'],quote=True)}" data-page="{path}"></script></head><body><header><div class="wrap mast"><a class="brand" href="./">The Practical Home<span>DIY Home Upgrades</span></a><nav class="nav" aria-label="Main navigation"><a href="./#shop">Shop</a><a href="guides.html">Buying guides</a><a data-event="rss_open" href="feed.xml">RSS</a><details><summary>Site desk</summary><div class="dropdown">{ops}</div></details></nav></div></header><div class="disclosure">{disclosure}</div><main class="wrap">{body}</main><footer><div class="wrap"><strong>The Practical Home</strong><p>{disclosure}</p><nav aria-label="Site desk and feed">{ops}<a data-event="rss_open" href="feed.xml">RSS feed</a></nav></div></footer></body></html>''')
def table(headers,rows): return '<div class="scroll" tabindex="0"><table><thead><tr>'+''.join(f'<th scope="col">{e(h)}</th>' for h in headers)+'</tr></thead><tbody>'+''.join('<tr>'+''.join(f'<td>{c}</td>' for c in row)+'</tr>' for row in rows)+'</tbody></table></div>'
def section(title,body): return f'<section class="section"><h1>{title}</h1>{body}</section>'
def approval(r):
    if not r['specialLink']: return False
    assert not r.get('duplicateOf') and all(r[k] for k in ('intendedAsin','officialListing','confirmedOn','confirmationSource','trackingReportSource','policyReviewedOn'))
    assert re.fullmatch('[A-Z0-9]{10}',r['intendedAsin'])
    for k in ('confirmedOn','policyReviewedOn'):
        from datetime import date
        date.fromisoformat(r[k])
    for k in ('officialListing','specialLink'):
        u=urlsplit(r[k]); assert u.scheme=='https' and u.netloc=='www.amazon.com' and u.path=='/dp/'+r['intendedAsin']
    assert parse_qs(urlsplit(r['specialLink']).query).get('tag')==[data['trackingId']]
    return True
topics=[('Wallpaper smoothing kit','Check the tools your wall covering calls for and which surfaces they are meant to touch.'),('Under-cabinet paper towel holder','Measure the roll and the space you need to remove it; check the installation method against the cabinet finish.'),('Pots and pans organizer','Measure your widest pan and tallest lid, and check fit with the cabinet door closed.')]
product_cards=''.join(f'<article class="card"><div class="eyebrow">Before you buy</div><h3>{e(t)}</h3><p>{e(d)}</p></article>' for t,d in topics)
