page('index.html','Kitchen upgrades worth comparing','Practical buying checklists for air fryers and countertop appliances.',f'''<section class="hero"><div><div class="eyebrow">Kitchen edit / Holiday hosting</div><h1>Small upgrades for a better home.</h1><p>Compare wallpaper tools, kitchen storage and countertop appliances by how they fit your space and routine.</p><a class="btn" href="guides.html">Explore buying guides →</a></div><img src="assets/kitchen.jpg" alt="Illustration of a basket air fryer on a kitchen counter"></section><section id="shop" class="section"><div class="eyebrow">The shopping desk</div><h2>Tools and storage to compare</h2><div class="cards">{product_cards}</div>{('<div class="cards">'+shop+'</div>') if shop else '<p>No individual products are listed yet. Start with these checklists to narrow down what you need.</p>'}<h2>Countertop appliance guides</h2><div class="cards">{cards}</div></section><aside class="endcap"><h3>Follow the next kitchen guide</h3><p>Add our RSS feed to your reader. No email address needed.</p><a data-event="rss_open" class="btn" href="feed.xml">Get the RSS feed →</a></aside>''')
page('guides.html','Buying guides','Air fryer and countertop appliance buying questions.',section('Buying guides',f'<p>Kitchen appliances · Practical questions to ask before you buy.</p><div class="cards">{cards}</div>'))
for s,t,d,copy in guides:
    page(s+'.html',t,d,f'<article class="section prose"><div class="eyebrow">Kitchen buying guide</div><h1>{e(t)}</h1><p class="muted">The Practical Home editorial desk · <time datetime="2026-11-20">November 20, 2026</time></p><p><strong>{e(d)}</strong></p><p>{e(copy)}</p><h2>One safety check before buying</h2><p>USDA advises against overcrowding an air fryer because it can restrict airflow and prevent proper cooking. Check food with a thermometer. {link(usda,"Read USDA food-safety guidance")}.</p><p class="muted">A buying checklist, not a hands-on test or an endorsement of a particular model.</p><h2>Keep comparing</h2><ul>'+''.join(f'<li>{link(other+".html",name)}</li>' for other,name,*_ in guides if other!=s)+'</ul></article>')
rows=[]
for r in data['submissions']:
    rows.append([e(r['id']), '<code>'+e(r['url'])+'</code>',*[e(r[k] or '') for k in ('intendedAsin','officialListing','confirmedOn','confirmationSource')], link(r['observedRedirect'],r['observedTitle']) .replace('<a ', '<a rel="sponsored noopener" ')+'<br>'+e(r['observedRedirect'])+' · '+e(r['observedOn']), 'Duplicate of '+r['duplicateOf']+'; unverified' if r.get('duplicateOf') else 'Unverified',link(asin,'Amazon ASIN guidance')+' · '+link(checker,'Tag checks')])
page('research.html','Research register','Submitted product links and their verification status.',section('Research register','<p>Four submissions, three distinct URLs. Blank fields are unverified. The observed redirect is not evidence of intended product identity.</p>'+table(['ID','Submitted URL','Intended ASIN','Official listing','Confirmed on','Confirmation source','Observed redirect','Status','Verification guidance'],rows)))
page('review.html','Flagged for Review','Unverified items and next evidence required.',section('Flagged for Review',table(['Item','Finding','Evidence required','Official guidance'],[
    ['S01–S04','Three Amazon destinations were observed: wallpaper tools, a paper towel holder, and a cookware organizer. These are not air fryers and do not establish intent or affiliate compliance.','Confirm the intended listing and ASIN for each submission; record redirect separately.',link(asin,'Amazon ASIN guidance')],['S03','Exact duplicate of S02 in the input.','Keep both records but do not create a second offer.',link(checker,'Amazon link verification')],['Tracking ID','<code>shopnow047c-20</code> supplied; ownership and attribution unverified.','Generate one Special Link per product in the enrolled account. Confirm destination and tag, then check first-party reporting without placing a self-order.',link(checker,'Amazon tag checks')+' · '+link(reports,'Amazon reports')],['Product data','No authorized catalog data or signed-in reports available. No prices, review counts, rankings, commissions, or forecasts published.','Review source authorization, display rules, expiry, and disclosure before enabling product data.',link(policy,'Amazon program policies')],['Search Console / measurement','No verified Search Console property or production analytics service configured.','Verify site ownership, submit the sitemap, deploy collector and check real event receipts.',link(google,'Google Search Console API')]])))
page('campaign.html','Campaign ledger','Campaign measurements and first-party provenance.',section('Campaign ledger','<p>No authorized report rows have been imported. Empty is not zero. No conversion score or revenue forecast is available.</p>'+table(['Timestamp','Source','Channel','Eligible sessions','Clicks','Reported orders','Official reference'],[['','','','','','',link(reports,'Amazon reporting guide')]])+'<p>'+link('data/campaign.csv','Download empty ledger schema')+'</p><p>Keep dated report references, timezone, reporting window, channel and tracking ID with each future import. Do not combine Amazon-reported clicks and local click totals as if they were the same metric. Eligible sessions remain blank until an authorized first-party source defines and supplies them.</p>'))
page('about.html','Executive summary','Publication priorities, compliance and evidence.',section('Executive summary',f'<div class="prose"><p>The Practical Home launches with four kitchen buying guides. The submitted URLs were observed landing on wallpaper tools and kitchen storage, not air fryers. Product intent and attribution remain unconfirmed, so no affiliate offers are live. The lead image is illustrative, not a verified product photo.</p><h2>Publishing plan</h2><p>Review search queries and landing pages monthly; aim for one new guide each month when measured queries and reliable sources justify it. Review seasonal links before major shopping periods. Each new guide goes in the sitemap and RSS on build. RSS is the reader follow option; this site does not collect email addresses.</p><p>{link("sitemap.xml","Sitemap")} · {link(google,"Search Console guidance")}</p><h2>Publishing gate</h2><p>Before enabling an offer, confirm the ASIN and listing from official evidence, document the tracking check, and review disclosures and program policies. The build blocks incomplete offer records; it does not authenticate evidence. Do not scrape listings or use restricted Program Content for AI without explicit authorization. AI drafts, rankings, and comparison claims are not auto-published.</p><p>{link(agreement,"Associates Agreement")} · {link(policy,"Amazon policies")} · {link(ftc,"FTC endorsement guidance")}</p><h2>What to measure</h2><p>Use Search Console queries and page performance to choose topics. Compare authorized aggregate results before changing placement or making a performance claim; look at local outbound clicks separately from Amazon orders.</p></div>'))
page('privacy.html','Privacy and measurement','What the website collects and what it does not.',section('Privacy and measurement',f'<div class="prose"><p>First-party analytics collector: <strong>{"Configured" if data["analyticsEndpoint"] else "Not configured"}</strong>. When enabled, the site sends aggregate events for page views, guide views, RSS link clicks, and affiliate link clicks. Reported orders are an authorized report import, never a browser event or a purchase inferred from a click.</p><p>The collector stores day, event name, page path and count only. The site does not set analytics cookies, store visitor IDs, or send full referrer or query strings. The hosting provider may independently process connection data.</p><p>{link(reports,"How Amazon reports clicks and orders")}</p></div>'))
Path('sitemap.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><urlset xmlns="http://www.sitemaps.org/schemas/sitemap/0.9">'+''.join(f'<url><loc>{x(u)}</loc></url>' for u in pages)+'</urlset>\n')
Path('feed.xml').write_text('<?xml version="1.0" encoding="UTF-8"?><rss version="2.0"><channel><title>The Practical Home</title><link>'+base+'</link><description>Practical kitchen buying guides</description>'+''.join(f'<item><title>{x(t)}</title><link>{base}{s}.html</link><guid>{base}{s}.html</guid><description>{x(d)}</description><pubDate>Fri, 20 Nov 2026 00:00:00 GMT</pubDate></item>' for s,t,d,_ in guides)+'</channel></rss>\n')
